### Approach
1. **Check for Null Inputs**: Ensure both linked lists are valid and not null.
2. **Merge the Lists**: Use a two-pointer technique to merge the two sorted lists in ascending order.
3. **Remove Duplicates**: While merging, check for duplicates and ensure each value is only included once.
4. **Maintain Order**: Since both lists are already sorted, we can merge them in a way that maintains the order and avoids duplicates efficiently.

### Solution Code
```java
public class MergeSortedLinkedLists {

    // Definition for singly-linked list.
    public static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
            this.next = null;
        }
    }

    /**
     * Merges two sorted linked lists in ascending order without duplicates.
     * Time Complexity: O(n), Space Complexity: O(1)
     * @param list1 The first sorted linked list.
     * @param list2 The second sorted linked list.
     * @return The merged sorted linked list without duplicates.
     * @throws IllegalArgumentException if either list is null.
     */
    public static ListNode mergeLists(ListNode list1, ListNode list2) {
        // Validate inputs
        if (list1 == null) {
            throw new IllegalArgumentException("First list cannot be null.");
        }
        if (list2 == null) {
            throw new IllegalArgumentException("Second list cannot be null.");
        }

        // Initialize pointers for both lists
        ListNode ptr1 = list1;
        ListNode ptr2 = list2;

        // Create a dummy node to build the merged list
        ListNode dummy = new ListNode(0);
        ListNode current = dummy;

        // Merge the two lists while maintaining order and removing duplicates
        while (ptr1 != null && ptr2 != null) {
            // Compare values of current nodes in both lists
            if (ptr1.val < ptr2.val) {
                // Check for duplicates in the merged list
                if (current.next == null || current.next.val != ptr1.val) {
                    current.next = ptr1;
                    current = current.next;
                }
                ptr1 = ptr1.next;
            } else if (ptr1.val > ptr2.val) {
                // Check for duplicates in the merged list
                if (current.next == null || current.next.val != ptr2.val) {
                    current.next = ptr2;
                    current = current.next;
                }
                ptr2 = ptr2.next;
            } else {
                // Values are equal, check for duplicates in the merged list
                if (current.next == null || current.next.val != ptr1.val) {
                    current.next = ptr1;
                    current = current.next;
                }
                // Move both pointers since values are equal
                ptr1 = ptr1.next;
                ptr2 = ptr2.next;
            }
        }

        // Append the remaining elements of the non-exhausted list
        while (ptr1 != null) {
            if (current.next == null || current.next.val != ptr1.val) {
                current.next = ptr1;
                current = current.next;
            }
            ptr1 = ptr1.next;
        }

        while (ptr2 != null) {
            if (current.next == null || current.next.val != ptr2.val) {
                current.next = ptr2;
                current = current.next;
            }
            ptr2 = ptr2.next;
        }

        // Return the merged list, skipping the dummy node
        return dummy.next;
    }

    /**
     * Helper method to print the linked list for testing purposes.
     * @param head The head of the linked list.
     */
    public static void printList(ListNode head) {
        ListNode current = head;
        while (current != null) {
            System.out.print(current.val + " -> ");
            current = current.next;
        }
        System.out.println("null");
    }

    // Main method for testing
    public static void main(String[] args) {
        // Example usage
        ListNode list1 = new ListNode(1);
        list1.next = new ListNode(2);
        list1.next.next = new ListNode(3);

        ListNode list2 = new ListNode(2);
        list2.next = new ListNode(3);
        list2.next.next = new ListNode(4);

        try {
            ListNode mergedList = mergeLists(list1, list2);
            System.out.println("Merged List:");
            printList(mergedList);
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
```

