import { Directive, ElementRef, Renderer2, HostListener, Input, OnInit, OnDestroy } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

@Directive({
  selector: '[primeAlert]'
})
export class PrimeAlertDirective implements OnInit, OnDestroy {
  private inputElement: HTMLInputElement;
  private subscription: any;

  constructor(
    private el: ElementRef,
    private renderer: Renderer2,
    private sanitizer: DomSanitizer
  ) {}

  ngOnInit() {
    this.inputElement = this.el.nativeElement as HTMLInputElement;
    this.subscription = this.inputElement.addEventListener('input', this.handleInputChange.bind(this));
  }

  ngOnDestroy() {
    if (this.subscription) {
      this.subscription.remove();
    }
  }

  @HostListener('input', ['$event'])
  handleInputChange(event: Event) {
    const value = this.sanitizer.sanitize(SafeHtml.RESOURCE_URL, this.inputElement.value);
    const length = value.length;

    if (length > 5 && this.isPrime(length)) {
      const isEvenPrime = length === 2;
      const color = isEvenPrime ? 'green' : 'blue';
      this.showAlert(value, color);
    }
  }

  private isPrime(n: number): boolean {
    if (n <= 1) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;
    for (let i = 3; i <= Math.sqrt(n); i += 2) {
      if (n % i === 0) return false;
    }
    return true;
  }

