            int current = array[i];
            int complement = targetSum - current;

            // Check if the complement exists in the set and hasn't been used
            if (seen.contains(complement) && !usedPairs.contains(complement + "," + current)) {
                // Add the pair to the list
                pairs.add(new int[]{current, complement});
                // Mark the pair as used
                usedPairs.add(current + "," + complement);
            } else {
                // Add the current number to the set
                seen.add(current);
            }
        }

        // Print the pairs
        if (pairs.isEmpty()) {
            System.out.println("No pairs found.");
        } else {
            System.out.println("Pairs found:");
            for (int[] pair : pairs) {
                System.out.println("(" + pair[0] + ", " + pair[1] + ")");
            }
        }
    }
}
